/* SSRF-Lite site — loads data.json generated by generate_ssrf_site.py */
"use strict";

const state = {
  data: null,
  fileById: new Map(),
  filtered: [],
  sortKey: "freq_mhz",
  sortDir: 1,
  view: "table",
  map: null,
  markerLayer: null,
  libCategory: "",
};

const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));
const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  })[c]);
const fmtFreq = (f) => (f != null ? f.toFixed(4) : "");

const BANDS = ["HF", "6m", "VHF", "1.25m", "UHF", "23cm", "SHF+"];
function bandOf(freq) {
  if (freq == null) return "";
  if (freq < 30) return "HF";
  if (freq < 54) return "6m";
  if (freq < 148) return "VHF";
  if (freq < 225) return "1.25m";
  if (freq < 512) return "UHF";
  if (freq < 1300) return "23cm";
  return "SHF+";
}

const SERVICE_LABELS = {
  amateur: "Amateur",
  gmrs: "GMRS",
  frs: "FRS",
  murs: "MURS",
  pmr446: "PMR446",
  noaa_weather_radio: "NOAA Weather",
  marine: "Marine VHF",
  aviation: "Aviation",
  railroad_aar: "Railroad (AAR)",
  public_safety_part90: "Public safety",
  business_itinerant_part90: "Business / itinerant",
};
const serviceLabel = (id) =>
  SERVICE_LABELS[id] ?? String(id ?? "").replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

const CATEGORY_LABELS = {
  system: ["Systems", "Location-based infrastructure: repeaters, simulcast networks, agency and business radio, by geography."],
  plan: ["Channel plans", "Portable frequency sets that are the same everywhere: GMRS, MURS, marine, airband, amateur simplex."],
  custom: ["Custom systems", "Special-purpose references such as hotspots and templates."],
  other: ["Other", ""],
};
const CATEGORY_ORDER = ["system", "plan", "custom", "other"];

const REGION_LABELS = {
  US: "United States", EU: "Europe", Global: "Global",
  AL: "Alabama", AK: "Alaska", AZ: "Arizona", AR: "Arkansas", CA: "California", CO: "Colorado",
  CT: "Connecticut", DE: "Delaware", FL: "Florida", GA: "Georgia", HI: "Hawaii", ID: "Idaho",
  IL: "Illinois", IN: "Indiana", IA: "Iowa", KS: "Kansas", KY: "Kentucky", LA: "Louisiana",
  ME: "Maine", MD: "Maryland", MA: "Massachusetts", MI: "Michigan", MN: "Minnesota",
  MS: "Mississippi", MO: "Missouri", MT: "Montana", NE: "Nebraska", NV: "Nevada",
  NH: "New Hampshire", NJ: "New Jersey", NM: "New Mexico", NY: "New York", NC: "North Carolina",
  ND: "North Dakota", OH: "Ohio", OK: "Oklahoma", OR: "Oregon", PA: "Pennsylvania",
  RI: "Rhode Island", SC: "South Carolina", SD: "South Dakota", TN: "Tennessee", TX: "Texas",
  UT: "Utah", VT: "Vermont", VA: "Virginia", WA: "Washington", WV: "West Virginia",
  WI: "Wisconsin", WY: "Wyoming", DC: "District of Columbia",
};
function groupLabel(group) {
  const parts = String(group ?? "").split(" / ").filter(Boolean);
  if (!parts.length) return "Global";
  const last = parts[parts.length - 1];
  const label = REGION_LABELS[last] ?? last;
  return parts.length > 1 && REGION_LABELS[parts[0]] && parts[0] !== last
    ? `${label}, ${parts[0]}`
    : label;
}
// Insert spaces into CamelCase folder names like "DownersGrove".
const placeLabel = (s) => String(s ?? "").replace(/([a-z])([A-Z])/g, "$1 $2");

/* ---------- boot ---------- */

async function init() {
  const resp = await fetch("data.json");
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
  state.data = await resp.json();
  for (const f of state.data.files) state.fileById.set(f.id, f);
  for (const c of state.data.channels) {
    const f = state.fileById.get(c.file);
    c.file_title = f ? f.title : c.file;
    c.band = bandOf(c.freq_mhz);
  }

  $("#generated").textContent = `Data generated ${state.data.generated} · `;
  renderStats();
  populateFilters();
  bindEvents();
  applyHash();
  renderLibrary();
}

function renderStats() {
  const chans = state.data.channels;
  const sites = new Set(chans.filter((c) => c.lat != null).map((c) => `${c.lat},${c.lon}`));
  const services = new Set(chans.map((c) => c.service).filter(Boolean));
  $("#stat-channels").textContent = chans.length.toLocaleString();
  $("#stat-files").textContent = state.data.files.length.toLocaleString();
  $("#stat-sites").textContent = sites.size.toLocaleString();
  $("#stat-services").textContent = services.size.toLocaleString();
  $("#stats").hidden = false;
}

function populateFilters() {
  const chans = state.data.channels;
  const services = [...new Set(chans.map((c) => c.service).filter(Boolean))]
    .sort((a, b) => serviceLabel(a).localeCompare(serviceLabel(b)));
  fillSelect("#filter-service", services.map((s) => [s, serviceLabel(s)]));
  const modes = [...new Set(chans.map((c) => c.mode).filter(Boolean))].sort();
  fillSelect("#filter-mode", modes.map((m) => [m, m]));
  const bands = new Set(chans.map((c) => c.band).filter(Boolean));
  fillSelect("#filter-band", BANDS.filter((b) => bands.has(b)).map((b) => [b, b]));
  const files = [...state.data.files].sort((a, b) => a.title.localeCompare(b.title));
  fillSelect("#filter-file", files.map((f) => [f.id, f.title]));
}

function fillSelect(sel, pairs) {
  const el = $(sel);
  for (const [value, label] of pairs) {
    const opt = document.createElement("option");
    opt.value = value;
    opt.textContent = label;
    el.appendChild(opt);
  }
}

function bindEvents() {
  for (const id of ["#search", "#filter-service", "#filter-mode", "#filter-band", "#filter-file"]) {
    $(id).addEventListener("input", () => { applyFilters(); pushHash(); });
  }
  $("#export-csv").addEventListener("click", exportCsv);
  $("#clear-filters").addEventListener("click", () => { setFilters({}); applyFilters(); pushHash(); });
  $("#active-filters").addEventListener("click", (ev) => {
    const btn = ev.target.closest("button[data-clear]");
    if (!btn) return;
    setFilters({ ...currentFilters(), [btn.dataset.clear]: "" });
    applyFilters();
    pushHash();
  });
  for (const btn of $$(".seg [data-view]")) {
    btn.addEventListener("click", () => { setView(btn.dataset.view); pushHash(); });
  }
  for (const th of $$("#channel-table th[data-sort]")) {
    th.addEventListener("click", () => {
      const key = th.dataset.sort;
      if (state.sortKey === key) state.sortDir *= -1;
      else { state.sortKey = key; state.sortDir = 1; }
      applyFilters();
    });
  }
  $("#lib-search").addEventListener("input", renderLibrary);
  for (const btn of $$("#lib-category button")) {
    btn.addEventListener("click", () => {
      state.libCategory = btn.dataset.cat;
      for (const b of $$("#lib-category button")) b.classList.toggle("active", b === btn);
      renderLibrary();
    });
  }
  $("#library-groups").addEventListener("click", (ev) => {
    const btn = ev.target.closest("button[data-browse]");
    if (!btn) return;
    browseFile(btn.dataset.browse);
  });
  window.addEventListener("hashchange", applyHash);
}

/* ---------- filters + URL state ---------- */

const FILTER_KEYS = ["q", "service", "mode", "band", "file"];
const FILTER_INPUTS = {
  q: "#search", service: "#filter-service", mode: "#filter-mode", band: "#filter-band", file: "#filter-file",
};

function currentFilters() {
  const out = {};
  for (const k of FILTER_KEYS) out[k] = $(FILTER_INPUTS[k]).value.trim();
  return out;
}

function setFilters(values) {
  for (const k of FILTER_KEYS) $(FILTER_INPUTS[k]).value = values[k] ?? "";
}

function pushHash() {
  const params = new URLSearchParams();
  for (const [k, v] of Object.entries(currentFilters())) if (v) params.set(k, v);
  if (state.view !== "table") params.set("view", state.view);
  const qs = params.toString();
  const target = qs ? `#browse?${qs}` : location.pathname + location.search;
  // Filter changes should not scroll the page or spam history.
  history.replaceState(null, "", target);
}

function applyHash() {
  const raw = location.hash.replace(/^#/, "");
  if (!raw.startsWith("browse?")) {
    if (!state.filtered.length) applyFilters();
    return;
  }
  const params = new URLSearchParams(raw.slice("browse?".length));
  const values = {};
  for (const k of FILTER_KEYS) values[k] = params.get(k) ?? "";
  setFilters(values);
  setView(params.get("view") === "map" ? "map" : "table");
  applyFilters();
  $("#browse").scrollIntoView({ block: "start" });
}

function browseFile(fileId) {
  setFilters({ file: fileId });
  setView("table");
  applyFilters();
  pushHash();
  $("#browse").scrollIntoView({ block: "start" });
}

function setView(view) {
  state.view = view;
  for (const btn of $$(".seg [data-view]")) btn.classList.toggle("active", btn.dataset.view === view);
  $("#view-table").classList.toggle("active", view === "table");
  $("#view-map").classList.toggle("active", view === "map");
  if (view === "map") initMap();
}

function applyFilters() {
  const f = currentFilters();
  const q = f.q.toLowerCase();

  state.filtered = state.data.channels.filter((c) => {
    if (f.service && c.service !== f.service) return false;
    if (f.mode && c.mode !== f.mode) return false;
    if (f.band && c.band !== f.band) return false;
    if (f.file && c.file !== f.file) return false;
    if (q) {
      const hay = [
        c.name, c.call_sign, c.org, c.loc_name, c.notes, c.mode, c.mode_detail,
        c.service, serviceLabel(c.service), c.usage, c.file_title, fmtFreq(c.freq_mhz),
      ].join(" ").toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  const { sortKey, sortDir } = state;
  state.filtered.sort((a, b) => {
    const av = a[sortKey], bv = b[sortKey];
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    if (typeof av === "number") return (av - bv) * sortDir;
    return String(av).localeCompare(String(bv)) * sortDir;
  });

  for (const th of $$("#channel-table th[data-sort]")) {
    th.classList.toggle("sorted-asc", th.dataset.sort === sortKey && sortDir === 1);
    th.classList.toggle("sorted-desc", th.dataset.sort === sortKey && sortDir === -1);
  }

  const total = state.data.channels.length;
  $("#result-count").textContent =
    state.filtered.length === total
      ? `${total.toLocaleString()} channels`
      : `${state.filtered.length.toLocaleString()} of ${total.toLocaleString()} channels`;
  renderActiveFilters(f);
  renderTable();
  if (state.map) renderMarkers(true);
}

function renderActiveFilters(f) {
  const chips = [];
  const labelFor = {
    q: (v) => `“${v}”`,
    service: (v) => serviceLabel(v),
    mode: (v) => v,
    band: (v) => v,
    file: (v) => state.fileById.get(v)?.title ?? v,
  };
  for (const k of FILTER_KEYS) {
    if (!f[k]) continue;
    chips.push(
      `<span class="chip">${esc(labelFor[k](f[k]))}` +
      `<button type="button" data-clear="${k}" aria-label="Remove filter">×</button></span>`
    );
  }
  $("#active-filters").innerHTML = chips.join("");
  $("#clear-filters").hidden = chips.length === 0;
}

/* ---------- table ---------- */

function renderTable() {
  if (!state.filtered.length) {
    $("#channel-table tbody").innerHTML =
      `<tr class="empty"><td colspan="10">No channels match these filters.</td></tr>`;
    return;
  }
  const rows = state.filtered.map((c) => {
    const f = state.fileById.get(c.file);
    const src = f?.doc_url
      ? `<a href="${esc(f.doc_url)}" title="${esc(f.id)}">${esc(c.file_title)}</a>`
      : `<span class="muted" title="${esc(c.file)}">${esc(c.file_title)}</span>`;
    return `
    <tr>
      <td class="num">${fmtFreq(c.freq_mhz)}</td>
      <td class="num">${fmtFreq(c.input_mhz)}</td>
      <td>${esc(c.mode ?? "")}</td>
      <td class="muted">${esc(c.mode_detail ?? "")}</td>
      <td class="${c.name_derived ? "name derived" : "name"}"${c.name_derived ? ' title="No channel name in the data; label derived from the record ID"' : ""}>${esc(c.name)}</td>
      <td class="mono">${esc(c.call_sign ?? "")}</td>
      <td class="muted">${esc(c.loc_name ?? "")}</td>
      <td>${c.service ? `<span class="badge">${esc(serviceLabel(c.service))}</span>` : ""}</td>
      <td class="notes">${esc(c.notes ?? "")}</td>
      <td class="src">${src}</td>
    </tr>`;
  });
  $("#channel-table tbody").innerHTML = rows.join("");
}

const CSV_COLUMNS = [
  ["freq_mhz", "Freq (MHz)"],
  ["input_mhz", "Input (MHz)"],
  ["mode", "Mode"],
  ["mode_detail", "Tone / CC"],
  ["name", "Name"],
  ["service", "Service"],
  ["usage", "Usage"],
  ["call_sign", "Callsign"],
  ["org", "Organization"],
  ["loc_name", "Location"],
  ["lat", "Lat"],
  ["lon", "Lon"],
  ["notes", "Notes"],
  ["file_title", "Source"],
  ["file", "Source File"],
];

function exportCsv() {
  const csvField = (v) => {
    const s = String(v ?? "");
    return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const lines = [CSV_COLUMNS.map(([, label]) => csvField(label)).join(",")];
  for (const c of state.filtered) lines.push(CSV_COLUMNS.map(([key]) => csvField(c[key])).join(","));
  const blob = new Blob([lines.join("\r\n") + "\r\n"], { type: "text/csv;charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `ssrf-lite-channels-${state.data.generated}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
}

/* ---------- map ---------- */

function initMap() {
  if (state.map) {
    state.map.invalidateSize();
    return;
  }
  state.map = L.map("map").setView([41.88, -87.63], 8);
  L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png", {
    attribution:
      '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> ' +
      'contributors &copy; <a href="https://carto.com/attributions">CARTO</a>',
    maxZoom: 19,
  }).addTo(state.map);
  state.markerLayer = L.layerGroup().addTo(state.map);
  renderMarkers(true);
}

function renderMarkers(fit = false) {
  state.markerLayer.clearLayers();

  const sites = new Map();
  for (const c of state.filtered) {
    if (c.lat == null || c.lon == null) continue;
    const key = `${c.lat},${c.lon}`;
    if (!sites.has(key)) sites.set(key, { lat: c.lat, lon: c.lon, name: c.loc_name, chans: [], files: new Set() });
    const site = sites.get(key);
    site.chans.push(c);
    site.files.add(c.file);
  }

  const latlngs = [];
  for (const site of sites.values()) {
    latlngs.push([site.lat, site.lon]);
    const chans = [...site.chans].sort((a, b) => (a.freq_mhz ?? 0) - (b.freq_mhz ?? 0));
    const lines = chans.slice(0, 12).map((c) =>
      `<div class="popup-chan">${fmtFreq(c.freq_mhz) || "—"} ${esc(c.mode ?? "")} — ${esc(c.name)}` +
      `${c.call_sign ? " (" + esc(c.call_sign) + ")" : ""}</div>`
    );
    if (chans.length > 12) lines.push(`<div class="popup-more">…and ${chans.length - 12} more</div>`);
    const links = [...site.files]
      .map((id) => state.fileById.get(id))
      .filter((f) => f?.doc_url)
      .map((f) => `<a href="${esc(f.doc_url)}">${esc(f.title)}</a>`);
    if (links.length) lines.push(`<div class="popup-more">${links.join(" · ")}</div>`);
    const marker = L.circleMarker([site.lat, site.lon], {
      radius: 7, color: "#4fb3ff", weight: 2, fillColor: "#4fb3ff", fillOpacity: 0.35,
    });
    marker.bindPopup(`<div class="popup-title">${esc(site.name ?? "Site")}</div>${lines.join("")}`, { maxWidth: 360 });
    state.markerLayer.addLayer(marker);
  }

  if (fit && latlngs.length) state.map.fitBounds(L.latLngBounds(latlngs).pad(0.15));
}

/* ---------- library ---------- */

function renderLibrary() {
  const q = $("#lib-search").value.trim().toLowerCase();
  const counts = new Map();
  for (const c of state.data.channels) counts.set(c.file, (counts.get(c.file) ?? 0) + 1);

  const files = state.data.files.filter((f) => {
    if (state.libCategory && f.category !== state.libCategory) return false;
    if (!q) return true;
    const hay = [f.title, f.id, f.region, f.topic, ...f.services.map(serviceLabel), ...f.services].join(" ").toLowerCase();
    return hay.includes(q);
  });

  const byCategory = new Map();
  for (const f of files) {
    if (!byCategory.has(f.category)) byCategory.set(f.category, new Map());
    const groups = byCategory.get(f.category);
    const key = f.region_group || f.region || "Global";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(f);
  }

  const html = [];
  for (const cat of CATEGORY_ORDER) {
    const groups = byCategory.get(cat);
    if (!groups) continue;
    const [label, blurb] = CATEGORY_LABELS[cat];
    const n = [...groups.values()].reduce((a, g) => a + g.length, 0);
    html.push(`<div class="group"><h3>${esc(label)}</h3><p>${esc(blurb)}${blurb ? " · " : ""}${n} file${n === 1 ? "" : "s"}</p>`);
    const keys = [...groups.keys()].sort((a, b) => groupLabel(a).localeCompare(groupLabel(b)));
    for (const key of keys) {
      const cards = groups.get(key)
        .sort((a, b) => (a.region + a.title).localeCompare(b.region + b.title))
        .map((f) => renderCard(f, counts.get(f.id) ?? 0));
      const heading = keys.length > 1 || key !== "Global" ? `<h4>${esc(groupLabel(key))}</h4>` : "";
      html.push(`<div class="subgroup">${heading}<div class="cards">${cards.join("")}</div></div>`);
    }
    html.push("</div>");
  }
  $("#library-groups").innerHTML = html.join("") || `<div class="empty">No files match that filter.</div>`;
}

function renderCard(f, channelCount) {
  const place = f.region_group && f.region.startsWith(f.region_group)
    ? f.region.slice(f.region_group.length).replace(/^ \/ /, "")
    : f.region;
  const placeText = [placeLabel(place), f.topic ? serviceLabel(f.topic) : ""].filter(Boolean).join(" · ");
  const badges = f.services.map((s) => `<span class="badge">${esc(serviceLabel(s))}</span>`);
  if (f.local) badges.push(`<span class="badge warn">Local overlay</span>`);
  const title = f.doc_url ? `<a href="${esc(f.doc_url)}">${esc(f.title)}</a>` : esc(f.title);
  const srcs = (f.sources ?? []).map((s) =>
    s.url ? `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)}</a>` : esc(s.name)
  );
  const links = [`<button type="button" data-browse="${esc(f.id)}">Browse channels</button>`];
  if (f.doc_url) links.push(`<a href="${esc(f.doc_url)}">Details</a>`);
  if (f.url) links.push(`<a href="${esc(f.url)}" target="_blank" rel="noopener">YAML ↗</a>`);
  return `
    <article class="card">
      <h4>${title}</h4>
      ${placeText ? `<div class="region">${esc(placeText)}</div>` : ""}
      <div class="badges">${badges.join("")}</div>
      <dl>
        <dt>Channels</dt><dd>${channelCount}</dd>
        <dt>Sites</dt><dd>${f.counts?.locations ?? 0}</dd>
        ${f.lastmod ? `<dt>Updated</dt><dd>${esc(f.lastmod)}</dd>` : ""}
        ${srcs.length ? `<dt>Sources</dt><dd>${srcs.join(" · ")}</dd>` : ""}
      </dl>
      <div class="links">${links.join("")}</div>
    </article>`;
}

init().catch((err) => {
  $("#browse .wrap").insertAdjacentHTML(
    "afterbegin",
    `<p class="error">Failed to load data.json (${esc(err.message)}). Run <code>make site</code> to generate it.</p>`
  );
});
